// ============================================================
// NODE 3 — BUILD GEMINI PROMPT
// Merges form input + profile + blooms + strategies
// ============================================================

// --- Pull form input from trigger node ---
const form = $('1. Form Response Trigger').first().json;

// --- Pull profile data (key = col A, value = col B) ---
const profileRows = $('2a. Read Profile Tab').all().map(i => i.json);
const profile = {};
profileRows.forEach(row => {
  if (row['key'] && row['value']) {                          // ✅ FIX 1
    profile[row['key'].trim()] = String(row['value']).trim();
  }
});

// --- Pull Bloom's data ---
const bloomsRows = $('2b. Read Blooms Tab').all().map(i => i.json);
const bloomsText = bloomsRows.map(r =>
  `${r['level']}: ${r['all_verbs'] || ''}`                  // ✅ FIX 2
).join('\n');

// --- Pull strategies ---
const stratRows = $('2c. Read Strategies Tab').all().map(i => i.json);
const strategiesText = stratRows.map(r =>
  `- ${r['strategy']}: ${r['description']} (Best for: ${r['best_for']})`  // ✅ FIX 3
).join('\n');

// Helper to get field value trimming key whitespace
const f = (key) => {
  const match = Object.keys(form).find(k => k.trim() === key.trim());
  return match ? (form[match] || '') : '';
};

// Convert Google Sheets date serial to real date string
const excelDateToString = (serial) => {
  if (!serial || isNaN(serial)) return String(serial || '');
  const date = new Date((serial - 25569) * 86400 * 1000);
  return date.toISOString().split('T')[0]; // returns YYYY-MM-DD
};

const unitTitle     = f('Unit Title');
const unitCode      = f('Unit Code');
const className     = f('Class Name');
const numLearners   = String(f('Number of Learners'));
const weekNo        = String(f('Week Number'));
const weekDate      = excelDateToString(f('Date of Week (Monday)'));
const skillTask     = f('Skill or Job Task');
const rawObjectives = f('Raw Learning Objectives');
const session1Title = f('Session 1 Title');
const session1Hints = f('Session 1 — Topic Hints') || f('Session 1 - Topic Hints');
const session2Title = f('Session 2 Title');
const session2Hints = f('Session 2 — Topic Hints') || f('Session 2 - Topic Hints');
const specialInstr  = f('Special Instructions for AI') || 'None';

const hasSession2 = session2Title.trim().length > 0;

// --- Build the prompt ---
const prompt = `
You are an expert curriculum developer for TVET/college-level education in Kenya.
You write in formal, assessor-ready language aligned to KSTVET standards.
You MUST respond with valid JSON only. No explanation, no markdown, no preamble.

=== BLOOM'S TAXONOMY VERBS (use these for all learning outcomes) ===
${bloomsText}

For a Level 6 college class, PREFER verbs from levels 3-6 (Applying, Analysing, Evaluating, Creating).
Use levels 1-2 only for introductory or foundational sessions.

=== ACTIVE LEARNING STRATEGIES (use these for Trainee Activities) ===
${strategiesText}

Always name the specific strategy used (e.g. "Through Think-Pair-Share, trainees...").
Each session must use at least 2 different strategies.

=== TEACHER INPUT ===
Unit Title: ${unitTitle}
Unit Code: ${unitCode}
Class: ${className}
Learners: ${numLearners}
Week: ${weekNo}
Skill/Job Task: ${skillTask}
Raw Objectives: ${rawObjectives}
Session 1 Title: ${session1Title}
Session 1 Topic Hints: ${session1Hints}
${hasSession2 ? `Session 2 Title: ${session2Title}\nSession 2 Topic Hints: ${session2Hints}` : 'Session 2: NOT REQUIRED - leave session_2 fields as empty strings'}
Special Instructions: ${specialInstr}

=== OUTPUT FORMAT ===
Return ONLY this JSON structure. All values must be strings.

{
  "benchmarks": "4 benchmark statements separated by newlines, using Bloom's verbs (Define... / Identify... / Determine... / Apply...)",
  "session_1_outcomes": "3-4 learning outcomes starting with Bloom's verbs, each on a new line, starting with a dash",
  "session_1_keypoints": "Structured key learning points with sub-headings and bullet content, aligned to outcomes",
  "session_1_activities": "Trainee activities naming the strategy used. Format: 'Through [Strategy], trainees will [action].' One per outcome.",
  "session_1_references": "2-3 APA-formatted textbook references relevant to this topic",
  "session_1_resources": "3-5 physical or digital resources (models, images, software, handouts etc.)",
  "session_1_assessment": "Knowledge: [method]\nSkill: [method]\nAttitudes: [method]",
  "session_2_outcomes": "",
  "session_2_keypoints": "",
  "session_2_activities": "",
  "session_2_references": "",
  "session_2_resources": "",
  "session_2_assessment": ""
}
`;

return [{
  json: {
    prompt,
    // Pass through all values needed for doc filling
    unit_title: unitTitle,
    unit_code: unitCode,
    class_name: className,
    num_learners: numLearners,
    week_no: weekNo,
    week_date: weekDate,
    skill_task: skillTask,
    session_1_title: session1Title,
    session_2_title: session2Title,
    has_session_2: hasSession2,
    // Profile fields (pulled from Master Sheet Profile tab)
    trainer_name: profile['trainer_name'] || '',
    admission_no: profile['admission_no'] || '',
    institution: profile['institution'] || '',
    level: profile['level'] || '6',
    ref_learning_plan: profile['ref_learning_plan'] || 'KSTVET/TP/LP/FO7',
    template_doc_id: profile['learning_plan_template_id'] || '',
    output_folder_id: profile['output_folder_id'] || '',
    date_prepared: new Date().toLocaleDateString('en-GB', { day:'2-digit', month:'short', year:'numeric' })
  }
}];

// NODE 5 — PARSE GEMINI RESPONSE
const rawText = $input.first().json.text;

// Strip markdown code fences
const cleaned = rawText
  .replace(/```json/g, '')
  .replace(/```/g, '')
  .trim();

// Parse JSON
let ai;
try {
  ai = JSON.parse(cleaned);
} catch(e) {
  throw new Error('Failed to parse Gemini JSON: ' + cleaned.substring(0, 300));
}

const prev = $('3. Build Gemini Prompt').first().json;

return [{
  json: {
    '{{ref_learning_plan}}':        prev.ref_learning_plan,
    '{{unit_title}}':               prev.unit_title,
    '{{unit_code}}':                prev.unit_code,
    '{{trainer_name}}':             prev.trainer_name,
    '{{admission_no}}':             prev.admission_no,
    '{{institution}}':              prev.institution,
    '{{level}}':                    prev.level,
    '{{date_prepared}}':            prev.date_prepared,
    '{{num_learners}}':             prev.num_learners,
    '{{class_name}}':               prev.class_name,
    '{{skill_task}}':               prev.skill_task,
    '{{week_no}}':                  prev.week_no,
    '{{benchmarks}}':               ai.benchmarks,
    '{{session_1_title}}':          prev.session_1_title,
    '{{session_1_outcomes}}':       ai.session_1_outcomes,
    '{{session_1_keypoints}}':      ai.session_1_keypoints,
    '{{session_1_activities}}':     ai.session_1_activities,
    '{{session_1_references}}':     ai.session_1_references,
    '{{session_1_resources}}':      ai.session_1_resources,
    '{{session_1_assessment}}':     ai.session_1_assessment,
    '{{session_2_title}}':          prev.session_2_title,
    '{{session_2_outcomes}}':       ai.session_2_outcomes,
    '{{session_2_keypoints}}':      ai.session_2_keypoints,
    '{{session_2_activities}}':     ai.session_2_activities,
    '{{session_2_references}}':     ai.session_2_references,
    '{{session_2_resources}}':      ai.session_2_resources,
    '{{session_2_assessment}}':     ai.session_2_assessment,
    // Pass-through for nodes 6, 7, 8
    _template_doc_id:   prev.template_doc_id,
    _output_folder_id:  prev.output_folder_id,
    _class_name:        prev.class_name,
    _week_no:           prev.week_no,
    _unit_title:        prev.unit_title,
    _week_date:         prev.week_date
  }
}];

const p = $('5. Parse Gemini Response').first().json;
const docId = $('6. Copy Template in Drive').first().json.id;

const placeholders = [
  ['{{ref_learning_plan}}',     p['{{ref_learning_plan}}']],
  ['{{unit_title}}',            p['{{unit_title}}']],
  ['{{unit_code}}',             p['{{unit_code}}']],
  ['{{trainer_name}}',          p['{{trainer_name}}']],
  ['{{admission_no}}',          p['{{admission_no}}']],
  ['{{institution}}',           p['{{institution}}']],
  ['{{level}}',                 p['{{level}}']],
  ['{{date_prepared}}',         p['{{date_prepared}}']],
  ['{{num_learners}}',          p['{{num_learners}}']],
  ['{{class_name}}',            p['{{class_name}}']],
  ['{{skill_task}}',            p['{{skill_task}}']],
  ['{{week_no}}',               p['{{week_no}}']],
  ['{{benchmarks}}',            p['{{benchmarks}}']],
  ['{{session_1_title}}',       p['{{session_1_title}}']],
  ['{{session_1_outcomes}}',    p['{{session_1_outcomes}}']],
  ['{{session_1_keypoints}}',   p['{{session_1_keypoints}}']],
  ['{{session_1_activities}}',  p['{{session_1_activities}}']],
  ['{{session_1_references}}',  p['{{session_1_references}}']],
  ['{{session_1_resources}}',   p['{{session_1_resources}}']],
  ['{{session_1_assessment}}',  p['{{session_1_assessment}}']],
  ['{{session_2_title}}',       p['{{session_2_title}}']],
  ['{{session_2_outcomes}}',    p['{{session_2_outcomes}}']],
  ['{{session_2_keypoints}}',   p['{{session_2_keypoints}}']],
  ['{{session_2_activities}}',  p['{{session_2_activities}}']],
  ['{{session_2_references}}',  p['{{session_2_references}}']],
  ['{{session_2_resources}}',   p['{{session_2_resources}}']],
  ['{{session_2_assessment}}',  p['{{session_2_assessment}}']],
];

const requests = placeholders.map(([text, replaceText]) => ({
  replaceAllText: {
    containsText: { text, matchCase: true },
    replaceText: String(replaceText || '')
  }
}));

return [{
  json: {
    docId,
    body: { requests }
  }
}];
